// HLC tick on local write
let mut hlc = HLC::new(agent_id);
hlc.tick();  // wall_ms synced with system clock, counter++

// Or-Set wrap for KG reference
let ref_tag = Tag { node_id: agent_id, seq: hlc.counter };
let ref_entry = (entity_id, sourceId, sourcePath);
or_set.add((ref_entry, ref_tag));

// Delta: send (ref_entry, tag, hlc) to peer
let delta = ORSetDelta {
    adds: vec![(ref_entry, ref_tag)],
    state_vector: state_vec.clone(),  // max HLC per agent
};

// Peer merge
let payload = postcard::to_bytes(&delta)?;
webrtc_datachannel.send(payload);

// On receive: Or-Set semantics
peer_or_set.merge_delta(&incoming_delta);  // idempotent, commutative
peer_hlc.recv(&incoming_hlc);  // clock advancement
